/* globtable.h — lordos-testbench's comparison of a compositor's registry against LordOS's protocol table
 * (docs/wayland-protocols.json → expected_globals.h, generated by tools/gen-wayland-table.mjs, so the list can't drift).
 * Pure: no Wayland connection here, tested by tests/testbench_globals_test.c. */
#ifndef LORD_TESTBENCH_GLOBTABLE_H
#define LORD_TESTBENCH_GLOBTABLE_H

#include <stdint.h>
#include <stdio.h>

typedef struct { uint32_t name, version; char iface[64]; } Global;     /* one wl_registry.global event */

typedef struct {
    const char *iface;                  /* "xdg_wm_base" */
    uint32_t version;                   /* the version lord-server creates it with */
    const char *protocol;               /* the table's row: "xdg-shell" */
    int partial;                        /* the row says "partly" */
    const char *offered;                /* "" to every client, or "xwayland", "headset", "render-node", "unsandboxed" */
} TbExpect;

enum {
    GT_OFFERED,                         /* advertised at the expected version */
    GT_NEWER,                           /* advertised at a higher version than the table's */
    GT_OLDER,                           /* advertised at a lower version */
    GT_MISSING,                         /* not advertised, and the table says every client gets it */
    GT_NOT_HERE,                        /* not advertised, but it is offered only to some clients or machines */
};

typedef struct { int state; uint32_t advertised; } GtRow;
typedef struct { int expected, offered, newer, older, missing, not_here, extra; } GtSummary;

/* the table: TB_EXPECTED_N rows */
int gt_expected_count(void);
const TbExpect *gt_expected(int i);

/* Compares n advertised globals against the table. rows (gt_expected_count() of them) may be NULL. The same interface
 * advertised twice (wl_output, one per display) counts once, at its highest version. */
void gt_compare(const Global *g, int n, GtRow *rows, GtSummary *s);

/* "offered", "newer", "older", "missing", "not-here" */
const char *gt_state_name(int state);

/* Why a GT_NOT_HERE global may be absent, in words: "offered only to Xwayland" */
const char *gt_offered_why(const char *offered);

/* The comparison as one JSON object: {"source":"docs/wayland-protocols.json","expected":48,"offered":47,"newer":0,
 * "older":0,"missing":0,"notHere":1,"extra":["..."],"rows":[{"interface","protocol","expected","advertised","state",
 * "offeredTo","partial"}]}. Interface names from the compositor are written only as [A-Za-z0-9_] (anything else becomes '?'). */
void gt_json(FILE *o, const Global *g, int n);

/* The advertised globals as a JSON array [{"interface","version"}], names as above */
void gt_json_globals(FILE *o, const Global *g, int n);

#endif
